class Character:
    max_hp = 100

    def __init__(self, name):
        self.name = name
        self.__hp = Character.max_hp

    def hit(self, dmg):
        self.__hp = max(0, self.__hp - dmg)

    def heal(self, amount):
        self.__hp = min(Character.max_hp, self.__hp + amount)

    def get_hp(self):
        return self.__hp

    def is_alive(self):
        return self.__hp > 0

